create temporary table plumb_classified on commit drop as
select x.*, case when duplicate_in_file then 'duplicate_skipped' when existing_match then 'existing_matched'
 when shared_phone or shared_website or shared_address or existing_phone_conflict or dnc_match then 'review_required' else bucket end as final_bucket,
 concat_ws('; ',nullif(review_reason,''),case when shared_phone then 'Shared phone between different source business names' end,
 case when shared_website then 'Shared domain between different source businesses; verify ownership/location' end,
 case when shared_address then 'Shared street address between source businesses; verify identity' end,
 case when existing_phone_conflict then 'Phone already belongs to another CRM business; Admin review' end,
 case when dnc_match then 'Active DNC suppression' end) as final_reason
from (select s.*,
 exists(select 1 from plumb_source p where p.n<>s.n and p.name_key=s.name_key
   and ((p.phone_key<>'' and p.phone_key=s.phone_key) or (p.website is not null and regexp_replace(lower(p.website),'^https?://(www\.)?','','g')=regexp_replace(lower(s.website),'^https?://(www\.)?','','g')))
   and ((p.phone is not null and s.phone is null) or ((p.phone is null)=(s.phone is null) and ((p.website is not null and s.website is null) or ((p.website is null)=(s.website is null) and p.n<s.n))))) as duplicate_in_file,
 s.address ~ '^[0-9]' and exists(select 1 from plumb_source p where regexp_replace(regexp_replace(lower(p.address),'[, ]*canada$',''),'[^a-z0-9]','','g')=regexp_replace(regexp_replace(lower(s.address),'[, ]*canada$',''),'[^a-z0-9]','','g') and p.name_key<>s.name_key) as shared_address,
 s.phone_key<>'' and exists(select 1 from plumb_source p where p.phone_key=s.phone_key and p.name_key<>s.name_key) as shared_phone,
 s.website_key<>'' and exists(select 1 from plumb_source p where p.website_key=s.website_key and p.name_key<>s.name_key) as shared_website,
 exists(select 1 from public.call_list_leads l join public.call_list_segments seg on seg.id=l.segment_id and seg.crm='lead_generation'
 where regexp_replace(lower(l.business_name),'[^a-z0-9]','','g')=s.name_key and
 ((s.phone_key<>'' and right(regexp_replace(coalesce(l.phone,''),'[^0-9]','','g'),10)=s.phone_key)
 or (s.phone_key='' and s.website_key<>'' and split_part(regexp_replace(lower(coalesce(l.website,'')),'^https?://(www\.)?','','g'),'/',1)=s.website_key)))
 or exists(select 1 from public.leadgen_leads l where regexp_replace(lower(l.business_name),'[^a-z0-9]','','g')=s.name_key and
 ((s.phone_key<>'' and right(regexp_replace(coalesce(l.phone,''),'[^0-9]','','g'),10)=s.phone_key)
 or (s.phone_key='' and s.website_key<>'' and split_part(regexp_replace(lower(coalesce(l.website,'')),'^https?://(www\.)?','','g'),'/',1)=s.website_key))) as existing_match,
 s.phone_key<>'' and (exists(select 1 from public.call_list_leads l join public.call_list_segments seg on seg.id=l.segment_id and seg.crm='lead_generation'
 where right(regexp_replace(coalesce(l.phone,''),'[^0-9]','','g'),10)=s.phone_key and regexp_replace(lower(l.business_name),'[^a-z0-9]','','g')<>s.name_key)
 or exists(select 1 from public.leadgen_leads l where right(regexp_replace(coalesce(l.phone,''),'[^0-9]','','g'),10)=s.phone_key and regexp_replace(lower(l.business_name),'[^a-z0-9]','','g')<>s.name_key)) as existing_phone_conflict,
 exists(select 1 from public.crm_dnc_suppressions d where d.status='active' and d.removed_at is null and d.block_phone and s.phone_key<>'' and right(d.normalized_phone,10)=s.phone_key) as dnc_match
 from plumb_source s) x;
create temporary table plumb_baseline(table_name text,digest text) on commit drop;
do $$ declare t text; begin
 foreach t in array array['call_list_leads','call_list_segments','call_list_segment_agents','leadgen_campaigns','leadgen_campaign_agents','leadgen_clients','leadgen_leads','leadgen_call_logs','leadgen_followups','leadgen_appointments','leadgen_emails','leadgen_conversions','leadgen_users','leadgen_payroll','crm_payroll','crm_dnc_suppressions'] loop
  execute format('insert into plumb_baseline select %L,md5(to_jsonb(r)::text) from public.%I r',t,t);
 end loop;
end $$;
do $plumb$
declare v_client uuid; v_campaign uuid; v_henry uuid; v_admin uuid; v_no uuid; v_web uuid; v_review uuid; t text; changed boolean; v_file text:='campaign-125885-search-933634-plumber_winnipeg-mb-canada_67a95ec8f6cc9e3295eae763fc3e13d5.csv';
begin
 perform pg_advisory_xact_lock(hashtextextended('leadgen-plumbing-winnipeg-125885',0));
 if exists(select 1 from public.call_list_segments where source_file_name=v_file) then raise exception 'Source already imported; inspect existing segments instead of restarting'; end if;
 select id into strict v_client from public.leadgen_clients where name='Hidebrandt Web Services' and active and not coalesce(is_internal_test,false);
 select id into strict v_henry from public.leadgen_users where full_name='Henry Osuji' and role='agent' and active;
 select id into strict v_admin from public.leadgen_users where role='admin' and active and full_name='Winsalot Corp.';
 if exists(select 1 from public.leadgen_campaigns where client_id=v_client and (name='Lead Generation for Website & SEO — Winnipeg Plumbing Contractors' or target_industry ilike '%plumb%')) then raise exception 'Plumbing campaign already exists; inspect before import'; end if;
 insert into public.leadgen_campaigns(client_id,name,description,status,territory,target_industry,assigned_team,start_date,created_by,qualification_criteria)
 values(v_client,'Lead Generation for Website & SEO — Winnipeg Plumbing Contractors',
  'Winnipeg plumbing contractor website design and SEO prospecting for Henry Osuji. Website Review means agent qualification is required; no website defect is presumed.',
  'active','Winnipeg, Manitoba','Plumbing Contractors','Henry Osuji',current_date,v_admin,
  array['Confirm Winnipeg service area and plumbing business fit','Speak with decision maker','Qualify interest in website design, redesign or SEO without presuming a website defect']) returning id into v_campaign;
 insert into public.leadgen_campaign_agents(campaign_id,agent_id,assigned_by) values(v_campaign,v_henry,v_admin);
 insert into public.call_list_segments(crm,name,leadgen_campaign_id,status,created_by,campaign_name,industry,territory,source_file_name,source_file_type,total_uploaded_rows,deployed_at,deployed_by)
 values('lead_generation','Plumbing Contractors — Winnipeg, Manitoba — No Website — Hidebrandt Web Services — Henry Osuji',v_campaign,'active',v_admin,'Lead Generation for Website & SEO — Winnipeg Plumbing Contractors','Plumbing Contractors','Winnipeg, Manitoba',v_file,'csv',0,now(),v_admin) returning id into v_no;
 insert into public.call_list_segments(crm,name,leadgen_campaign_id,status,created_by,campaign_name,industry,territory,source_file_name,source_file_type,total_uploaded_rows,deployed_at,deployed_by)
 values('lead_generation','Plumbing Contractors — Winnipeg, Manitoba — Website Review — Hidebrandt Web Services — Henry Osuji',v_campaign,'active',v_admin,'Lead Generation for Website & SEO — Winnipeg Plumbing Contractors','Plumbing Contractors','Winnipeg, Manitoba',v_file,'csv',0,now(),v_admin) returning id into v_web;
 insert into public.call_list_segments(crm,name,leadgen_campaign_id,status,created_by,campaign_name,industry,territory,source_file_name,source_file_type,total_uploaded_rows)
 values('lead_generation','Plumbing Contractors — Winnipeg, Manitoba — Admin Review / Admin Only — Hidebrandt Web Services',v_campaign,'draft',v_admin,'Lead Generation for Website & SEO — Winnipeg Plumbing Contractors','Plumbing Contractors','Winnipeg, Manitoba',v_file,'csv',0) returning id into v_review;
 insert into public.call_list_segment_agents(segment_id,agent_id) values(v_no,v_henry),(v_web,v_henry);
 insert into public.call_list_leads(segment_id,source_row_number,business_name,phone,email,website,street_address,city,province,postal_code,country,industry,notes,extra_fields,is_possible_duplicate,duplicate_reason,dnc_flag,assigned_agent_id,created_by)
 select case final_bucket when 'no_website' then v_no when 'website_review' then v_web else v_review end,
 n,name,phone,email,website,address,city,'MB',postal,'Canada','Plumbing Contractors',
 case final_bucket when 'no_website' then 'No identifiable business website in source; confirm website status during the call. A social/directory profile is not a standalone business website.'||case when address is null then ' No street address in source (Manitoba area code); confirm Winnipeg service area.' else '' end
 when 'website_review' then 'Website present; qualify website design, redesign, SEO, mobile experience or lead-generation needs without presuming a defect.'||case when ssl_signal then ' Source crawler reported no SSL; unverified redesign signal.' else '' end||case when address is null then ' No street address in source (Manitoba area code); confirm Winnipeg service area.' else '' end
 else final_reason end,
 jsonb_build_object('source_file',v_file,'source_row',source,'website_category',final_bucket,'review_reason',final_reason),
 (shared_phone or shared_website or shared_address or existing_phone_conflict),case when shared_phone or shared_website or shared_address or existing_phone_conflict then final_reason end,dnc_match,
 case when final_bucket in ('no_website','website_review') then v_henry else null end,v_admin
 from plumb_classified where final_bucket not in ('duplicate_skipped','existing_matched');
 update public.call_list_segments s set total_uploaded_rows=(select count(*) from public.call_list_leads l where l.segment_id=s.id) where s.id in(v_no,v_web,v_review);
 foreach t in array array['call_list_leads','call_list_segments','call_list_segment_agents','leadgen_campaigns','leadgen_campaign_agents','leadgen_clients','leadgen_leads','leadgen_call_logs','leadgen_followups','leadgen_appointments','leadgen_emails','leadgen_conversions','leadgen_users','leadgen_payroll','crm_payroll','crm_dnc_suppressions'] loop
  execute format('select exists(select 1 from plumb_baseline b where b.table_name=%2$L and b.digest not in (select md5(to_jsonb(r)::text) from public.%1$I r))',t,t) into changed;
  if changed then raise exception 'Pre-existing rows changed in %; rollback',t; end if;
 end loop;
 if (select count(*) from plumb_source)<>387 then raise exception 'CSV row count mismatch'; end if;
 if (select md5(string_agg(n||'|'||coalesce(phone,'')||'|'||name||'|'||coalesce(website,'')||'|'||coalesce(address,'')||'|'||bucket||'|'||review_reason,E'
' order by n)) from plumb_source)<>'dd7e275ebf689c95c6178fa0fd5290ee' then raise exception 'Payload checksum mismatch; source data was altered'; end if;
 if (select count(*) from public.call_list_leads where segment_id in(v_no,v_web,v_review)) + (select count(*) from plumb_classified where final_bucket in('duplicate_skipped','existing_matched'))<>387 then raise exception 'Row reconciliation failed'; end if;
 if exists(select 1 from public.call_list_leads where segment_id in(v_no,v_web) and (assigned_agent_id is distinct from v_henry or dnc_flag)) then raise exception 'Wrong production agent or DNC lead'; end if;
 if exists(select 1 from public.call_list_segment_agents where segment_id in(v_no,v_web) and agent_id<>v_henry) then raise exception 'Wrong segment agent'; end if;
 if exists(select 1 from public.call_list_leads where segment_id=v_review and assigned_agent_id is not null) then raise exception 'Review leads must be unassigned'; end if;
 if exists(select 1 from public.call_list_segment_agents where segment_id=v_review) then raise exception 'Review segment must be Admin only'; end if;
 if (select count(*) from public.leadgen_campaign_agents where campaign_id=v_campaign)<>1 then raise exception 'Unexpected campaign agents'; end if;
end;
$plumb$;
select jsonb_build_object('csv_rows',(select count(*) from plumb_source),'classification',(select jsonb_object_agg(final_bucket,n) from(select final_bucket,count(*) n from plumb_classified group by final_bucket)x),
 'flagged_records',(select count(*) from plumb_classified where final_bucket='review_required' and(shared_phone or shared_website or shared_address or existing_phone_conflict)),
 'unverified_no_ssl_signals',(select count(*) from plumb_classified where final_bucket='website_review' and ssl_signal),'pre_existing_records_unchanged',true) as import_result;
commit;
